fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // We cast to i16 before subtracting to avoid overflow in edge cases,
    // then compare the absolute difference to tol.
    let diff = (a as i16) - (b as i16);
    diff.abs() < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Under the problem assumptions, `a.len() == b.len()` and `tol > 0`.
    // We can assert them to catch misuse in debug builds.
    assert!(tol > 0, "Tolerance must be strictly positive");
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    a.iter()
     .zip(b.iter())
     .map(|(&ai, &bi)| is_close_i8(ai, bi, tol))
     .collect()
}

